package solve_test

func solve(N int) string {
    // sum of decimal digits of N
    digitSum := 0
    tmp := N
    for tmp > 0 {
        digitSum += tmp % 10
        tmp /= 10
    }

    // binary representation of digitSum
    if digitSum == 0 {
        return "0"
    }

    // build binary string
    var bits []byte
    for digitSum > 0 {
        bits = append(bits, byte(digitSum&1))
        digitSum >>= 1
    }

    // reverse to get correct order
    for i := len(bits)/2; i >= 0; i-- {
        bits[i], bits[len(bits)-1-i] = bits[len(bits)-1-i], bits[i]
    }

    return string(bits)
}
