    "sort"
)

func sort_array(array []int) []int {
    if len(array) == 0 {
        return []int{}
    }

    first := array[0]
    last := array[len(array)-1]
    sum := first + last

    if sum%2 == 1 {
        // ascending order
        copy := make([]int, len(array))
        copy = append(copy, array...)
        sort.Ints(copy)
        return copy
    }

    // descending order
    copy := make([]int, len(array))
    copy = append(copy, array...)
    sort.Ints(copy)
    // reverse the copy
    for i := len(copy)/2; i >= 0; i-- {
        copy[i], copy[len(copy)-1-i] = copy[len(copy)-1-i], copy[i]
    }
    return copy
}
