    for _, ch := range c {
        deleteSet[ch] = struct{}{}
    }

    var result []rune
    for i := range s {
        if deleteSet[s[i]] == struct{}{} {
            continue
        }
        result = append(result, s[i])
    }

    var resStr string
    for _, r := range result {
        resStr += string(r)
    }

    var revRes string
    for i := len(resStr) - 1; i >= 0; i-- {
        revRes += string(resStr[i])
    }
    isPal := (resStr == revRes)

    return []interface{}{resStr, isPal}
}
