package simplify_test

import (
    "strconv"
    "strings"
)

func simplify(x string, n string) bool {
    var (
        xNum, xDen = parseFraction(x)
        nNum, nDen = parseFraction(n)
    )
    productNum := xNum * nNum
    productDen := xDen * nDen
    return productNum % productDen == 0
}

func parseFraction(s string) (int, int) {
    parts := strings.Split(s, "/")
    var num, den int
    num, _ = strconv.Atoi(parts[0])
    den, _ = strconv.Atoi(parts[1])
    return num, den
}
