use std::cmp::min;

/// From a supplied vector of numbers (of length at least two) select and return two that are the closest
/// to each other and return them in order (smaller number, larger number).
fn find_closest_elements(numbers: Vec<f64>) -> (f64, f64) {
    let mut sorted = numbers.clone();
    sorted.sort_unstable();

    let mut best_diff = f64::MAX;
    let mut best_pair = (f64::MIN, f64::MAX);

    for i in 1..sorted.len() {
        let diff = sorted[i] - sorted[i - 1];
        if diff < best_diff {
            best_diff = diff;
            best_pair = (sorted[i - 1], sorted[i]);
        }
    }
    best_pair
}
