fn correct_bracketing(brackets: String) -> bool {
    let mut stack = Vec::new();
    for ch in brackets.chars() {
        if ch == '<' {
            stack.push('<');
        } else if ch == '>' {
            if stack.is_empty() {
                return false;
            }
            stack.pop();
        }
        // Input is guaranteed to contain only '<' and '>', so no other case.
    }
    stack.is_empty()
}
