fn pluck(arr: Vec<isize>) -> Vec<isize> {
    let mut best_val = None;
    let mut best_idx = None;
    for (i, &v) in arr.iter().enumerate() {
        if v % 2 == 0 {
            if best_val == None || v < best_val {
                best_val = v;
                best_idx = i;
            }
        }
    }
    if best_val == None {
        return vec![];
    }
    return vec![best_val, best_idx];
}
