fn will_it_fly(q: Vec<isize>, w: isize) -> bool {
    // palindrome check
    let n = q.len();
    if n > 0 {
        let mut ok = true;
        for i in 0..(n / 2) {
            if q[i] != q[n - 1 - i] {
                ok = false;
                break;
            }
        }
        if !ok {
            return false;
        }
    }
    // sum condition
    let sum = q.iter().sum::<isize>();
    sum <= w
}
