fn solve(N: isize) -> String {
    let n_str = N.to_string();
    let mut total = 0;
    for ch in n_str.chars() {
        total += ch as u8 - b'0';
    }
    if total == 0 {
        return "0".to_string();
    }
    let mut bits = String::new();
    let mut tmp = total;
    while tmp > 0 {
        bits.push_str( (tmp % 2).to_string() );
        tmp /= 2;
    }
    bits.reverse();
    bits
}
```

