fn sort_array(array: Vec<isize>) -> Vec<isize> {
    if array.is_empty() {
        return array;
    }
    let first = array[0];
    let last = array[array.len() - 1];
    let sum = first + last;
    let mut sorted = array.clone();
    if sum % 2 == 1 { // odd → ascending
        sorted.sort();
    } else { // even → descending
        sorted.sort(); // sort ascending
        sorted.reverse();
    }
    sorted
}
