function mean_absolute_deviation(numbers: number[]): number {
  const n = numbers.length;
  if (n === 0) return 0;

  const mean = numbers.reduce((sum, val) => sum + val, 0) / n;
  const absDiffs = numbers.map(val => Math.abs(val - mean));
  const sumAbs = absDiffs.reduce((s, v) => s + v, 0);
  return sumAbs / n;
}
