```typescript
function do_algebra(operator: string[], operand: number[]): number {
    const precedence: Record<string, number> = {
        "**": 4,
        "*": 3,
        "//": 3,
        "+": 2,
        "-": 2
    };

    const valueStack: number[] = [];
    const opStack: string[] = [];

    for (let i = 0; i < operator.length; i++) {
        const op = operator[i];
        const val = operand[i];
        valueStack.push(val);

        while (opStack.length > 0 && precedence[opStack[opStack.length - 1]] >= precedence[op]) {
            const b = valueStack.pop();
            const a = valueStack.pop();
            const res = apply(opStack.pop(), a, b);
            valueStack.push(res);
        }
        opStack.push(op);
    }

    while (opStack.length > 0) {
        const b = valueStack.pop();
        const a = valueStack.pop();
        const res = apply(opStack.pop(), a, b);
        valueStack.push(res);
    }

    return valueStack[0];
}

function apply(op: string, a: number, b: number): number {
    switch (op) {
        case "**": return Math.pow(a, b);
        case "*": return a * b;
        case "//": return Math.floor(a / b);
        case "+": return a + b;
        case "-": return a - b;
        default: return 0; // never reached
    }
}
