        for (let i = 3; i * i <= x; i += 2) {
            if (x % i === 0) return false;
        }
        return true;
    }

    const result: number[] = [];
    for (let i = 2; i < n; i++) {
        if (isPrime(i)) result.push(i);
    }
    return result;
}

assert.deepEqual(count_up_to(5), [2, 3]);
assert.deepEqual(count_up_to(11), [2, 3, 5, 7]);
assert.deepEqual(count_up_to(0), []);
