assert.deepEqual(count_up_to(1), []);
assert.deepEqual(count_up_to(18), [2, 3, 5, 7, 11, 13, 17]);
assert.deepEqual(count_up_to(2), [2]);
assert.deepEqual(count_up_to(3), [2]);
