function countOnes(n: number): number {
  const x = Math.abs(n);
  let count = 0;
  while (x) {
    count += x & 1;
    x >>>= 1;
  }
  return count;
}

function sort_array(arr: number[]): number[] {
  return arr.slice().sort((a, b) => {
    const ca = countOnes(a);
    const cb = countOnes(b);
    if (ca !== cb) return ca - cb;
    return a - b;
  });
}
```

