function maximum(arr: number[], k: number): number[] {
  if (k === 0) return [];
  const sortedDesc = [...arr].sort((a, b) => b - a); // descending
  const topK = sortedDesc.slice(0, k);
  return topK.sort((a, b) => a - b); // ascending
}
