function largest_smallest_integers(lst: number[]): [number | undefined, number | undefined] {
  let maxNeg = -Infinity;
  let minPos = Infinity;
  let hasNeg = false;
  let hasPos = false;

  for (const x of lst) {
    if (x < 0) {
      hasNeg = true;
      if (x > maxNeg) maxNeg = x;
    } else if (x > 0) {
      hasPos = true;
      if (x < minPos) minPos = x;
    }
  }

  let a = hasNeg ? maxNeg : undefined;
  let b = hasPos ? minPos : undefined;

  return [a, b];
}
```

